import React, { useEffect, useState } from "react";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import axios from "axios";
import "../styles/main.css";

export default function AdminManageHome() {
  const [data, setData] = useState({
    bannerVideos: [],
    welcomeText: "",
    activities: [], // ✅ corrected
    threeCol: [],
    testimonialVideos: [], // ✅ corrected
  });

  const [loading, setLoading] = useState(false);

  // 🟢 Fetch home content on mount
  useEffect(() => {
    axios
      .get("http://localhost:5000/api/home")
      .then((res) => {
        setData({
          bannerVideos: res.data.bannerVideos || [],
          welcomeText: res.data.welcomeText || "",
          activities: res.data.activities || [],
          threeCol: res.data.threeCol || [],
          testimonialVideos: res.data.testimonialVideos || [],
        });
      })
      .catch((err) => console.error("❌ Error loading home data:", err));
  }, []);

  // 🟢 File upload (banner, activity, testimonial)
  const handleFileUpload = async (e, section) => {
    const file = e.target.files[0];
    if (!file) return;

    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await axios.post("http://localhost:5000/api/admin/home", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
        params: { section },
      });

      console.log("✅ Upload response:", res.data);

      if (res.data?.content?.[section]) {
        setData((prev) => ({
          ...prev,
          [section]: res.data.content[section],
        }));
      }
    } catch (err) {
      console.error("❌ Upload failed:", err);
      alert("Upload failed. Check console for details.");
    }
  };

  // 🟢 Delete media (client-side only)
  const handleDelete = (key, index) => {
    setData((prev) => ({
      ...prev,
      [key]: prev[key].filter((_, i) => i !== index),
    }));
  };

  // 🟢 3-column content management
  const addThreeCol = () => {
    setData((prev) => ({
      ...prev,
      threeCol: [...prev.threeCol, { title: "New Section", text: "" }],
    }));
  };

  const handleThreeColChange = (index, field, value) => {
    const updated = [...data.threeCol];
    updated[index][field] = value;
    setData({ ...data, threeCol: updated });
  };

  // 🟢 Save all home content
  const handleSave = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem("token");

      await axios.post("http://localhost:5000/api/admin/home", data, {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
      });

      alert("✅ Home Page content saved successfully!");
    } catch (err) {
      console.error("❌ Save failed:", err);
      alert("Save failed. Check console for details.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="admin-manage-home">
      <h1 className="page-title">🏠 Manage Home Page</h1>

      {/* 🎥 Banner Videos */}
      <section className="admin-section">
        <div className="section-header">
          <h2>🎥 Banner Videos</h2>
          <input
            type="file"
            accept="video/*"
            onChange={(e) => handleFileUpload(e, "bannerVideos")}
          />
        </div>

        <div className="video-preview-grid">
          {data.bannerVideos?.length > 0 ? (
            data.bannerVideos.map((vid, i) => (
              <div key={i} className="media-card">
                <video src={`http://localhost:5000${vid}`} controls />
                <button onClick={() => handleDelete("bannerVideos", i)}>🗑</button>
              </div>
            ))
          ) : (
            <p className="empty-msg">No videos added yet</p>
          )}
        </div>
      </section>

      {/* 👋 Welcome Text */}
      <section className="admin-section">
        <h2>👋 Welcome Text</h2>
        <ReactQuill
          theme="snow"
          value={data.welcomeText}
          onChange={(val) => setData({ ...data, welcomeText: val })}
        />
      </section>

      {/* 🏫 Activity Images */}
      <section className="admin-section">
        <div className="section-header">
          <h2>🏫 Activity Images</h2>
          <input
            type="file"
            accept="image/*"
            multiple
            onChange={(e) => handleFileUpload(e, "activities")}
          />
        </div>

        <div className="image-grid">
          {data.activities?.length > 0 ? (
            data.activities.map((img, i) => (
              <div key={i} className="media-card">
                <img src={`http://localhost:5000${img}`} alt="activity" />
                <button onClick={() => handleDelete("activities", i)}>🗑</button>
              </div>
            ))
          ) : (
            <p className="empty-msg">No activity images added yet</p>
          )}
        </div>
      </section>

      {/* 📰 Three Column Section */}
      {/* --- 3-Column Section (Latest News / Calendar / Video) --- */}
      <section className="admin-section">
        <h2>📰 3-Column Section (News / Calendar / Video)</h2>

        {/* Latest News */}
        <div className="three-col-item">
            <h4>Latest News</h4>
            <textarea
                value={data.threeColumnSection?.latestNews || ""}
                onChange={(e) =>
                    setData((prev) => ({
                        ...prev,
                        threeColumnSection: {
                            ...prev.threeColumnSection,
                            latestNews: e.target.value,
                        },
                    }))
                }
                placeholder="Enter latest news text"
            />
        </div>

        {/* Activity Calendar */}
        <div className="three-col-item">
            <h4>Activity Calendar</h4>
            <input
                type="file"
                accept="image/*"
                onChange={async (e) => {
                    const file = e.target.files[0];
                    if (!file) return;

                    const formData = new FormData();
                    formData.append("file", file);

                    try {
                        const res = await axios.post("http://localhost:5000/api/upload", formData, {
                                headers: { "Content-Type": "multipart/form-data" },
                        });
                        setData((prev) => ({
                            ...prev,
                            threeColumnSection: {
                                ...prev.threeColumnSection,
                                activityCalendar: res.data.url,
                            },
                        }));
                    } catch (err) {
                        console.error("Upload failed:", err);
                        alert("Upload failed: " + err.message);
                    }
                }}
            />
            {data.threeColumnSection?.activityCalendar && (
                <img
                    src={data.threeColumnSection.activityCalendar}
                    alt="Calendar"
                    style={{ width: "200px", marginTop: "10px" }}
                />
            )}
            <input
                type="text"
                placeholder="Calendar button link"
                value={data.threeColumnSection?.calendarButtonLink || ""}
                onChange={(e) =>
                    setData((prev) => ({
                        ...prev,
                        threeColumnSection: {
                            ...prev.threeColumnSection,
                            calendarButtonLink: e.target.value,
                        },
                    }))
                }
            />
        </div>

        {/* Video */}
        <div className="three-col-item">
            <h4>Video (YouTube)</h4>
            <input
                type="text"
                placeholder="Paste YouTube embed URL here"
                value={data.threeColumnSection?.video || ""}
                onChange={(e) =>
                    setData((prev) => ({
                        ...prev,
                        threeColumnSection: {
                            ...prev.threeColumnSection,
                            video: e.target.value,
                        },
                    }))
                }
            />
        </div>
      </section>


      {/* 💬 Testimonials */}
      <section className="admin-section">
        <div className="section-header">
          <h2>💬 Testimonial Videos</h2>
          <input
            type="file"
            accept="video/*"
            onChange={(e) => handleFileUpload(e, "testimonialVideos")}
          />
        </div>

        <div className="video-preview-grid">
          {data.testimonialVideos?.length > 0 ? (
            data.testimonialVideos.map((vid, i) => (
              <div key={i} className="media-card">
                <video src={`http://localhost:5000${vid}`} controls />
                <button onClick={() => handleDelete("testimonialVideos", i)}>🗑</button>
              </div>
            ))
          ) : (
            <p className="empty-msg">No testimonials yet</p>
          )}
        </div>
      </section>

      {/* 💾 Save Button */}
      <div className="save-wrapper">
        <button onClick={handleSave} disabled={loading} className="save-btn">
          {loading ? "Saving..." : "💾 Save Changes"}
        </button>
      </div>
    </div>
  );
}
